import './style.css';
import {equity,filterDates,pnl,stats} from './calculations';
import {backup,hasUserStorage,initial,load,loadLegacy,restore,save,setStorageUser} from './storage';
import {authorizeSheets,clearGoogleAuthorization,getGoogleUser,getOrCreateJournalSpreadsheet,readCloudState,readSheetsConfig,saveSheetsConfig,writeCloudState} from './googleSheets';
import type {AppState,Trade} from './types';

const AUTH_EMAIL_KEY='tradewise-google-email';
let signedInEmail=localStorage.getItem(AUTH_EMAIL_KEY)?.trim()||'';
if(signedInEmail)setStorageUser(signedInEmail);
let state:AppState=signedInEmail?load():initial,page='Overview',range='all',account='all',editing:string|null=null,toastTimer:number|undefined,sheetsConnected=false,syncTimer:number|undefined,cloudPollTimer:number|undefined,googleName='';
let positionRiskMode:'percent'|'fixed'='percent',positionRiskValue=1,positionStopPips=50,positionBalance:number|null=null,positionCurrency='',positionPair='EUR/USD',positionUnitsPerLot=100000,positionConversionRate:number|null=null;
const deletedTradeIds=new Set<string>();
function userStorageKey(key:string){return `tradewise:${encodeURIComponent(signedInEmail.toLowerCase())}:${key}`;}
const $=(s:string)=>document.querySelector(s) as HTMLElement;
const money=(n:number|null,cur=state.settings.currency)=>n===null?'—':new Intl.NumberFormat(undefined,{style:'currency',currency:cur,maximumFractionDigits:2}).format(n);
const nav=[['Overview','◫'],['Trade Journal','▤'],['Trading Calendar','▦'],['Strategies & Setups','⌁'],['Performance Analytics','⌁'],['Daily Reviews','☷'],['Risk Management','◇'],['Settings & Backup','⚙']];
function notify(msg:string){const el=$('#toast');if(!el){const error=$('#auth-error');if(error)error.textContent=msg;else console.warn(msg);return;}el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3200);}
function persist(){if(!save(state))notify('Storage is full. Export a backup and remove large attachments.');else{$('#saved').textContent='Saved locally · '+new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});if(sheetsConnected){clearTimeout(syncTimer);syncTimer=setTimeout(()=>syncSheets(false),700);}}}
function selectedTrades(){let ts=state.trades;if(account!=='all')ts=ts.filter(t=>t.accountId===account);if(range!=='all'){const from=new Date();from.setDate(from.getDate()-Number(range));ts=ts.filter(t=>new Date(t.date)>=from);}return ts;}
function title(){return page;}
function chart(ts:Trade[],starting=0){const points=equity(ts,starting);if(!points.length)return `<div class="chart-empty"><span class="chart-icon">↗</span><b>Your equity curve starts here</b><span>Log a closed trade to see your progress over time.</span></div>`;const vals=points.map(p=>p.balance),min=Math.min(0,...vals),max=Math.max(...vals),span=max-min||1;const coords=vals.map((v,i)=>`${24+i*552/Math.max(1,vals.length-1)},${180-(v-min)/span*145}`).join(' ');const area=`24,180 ${coords} ${24+(vals.length-1)*552/Math.max(1,vals.length-1)},180`;return `<svg class="equity-chart" viewBox="0 0 600 200" preserveAspectRatio="none"><defs><linearGradient id="fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#13ad79" stop-opacity=".22"/><stop offset="1" stop-color="#13ad79" stop-opacity="0"/></linearGradient></defs><path d="M ${area.replaceAll(' ',',')} Z" fill="url(#fill)"/><polyline points="${coords}" fill="none" stroke="#08a878" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${points.map((p,i)=>`<circle cx="${24+i*552/Math.max(1,points.length-1)}" cy="${180-(p.balance-min)/span*145}" r="3" fill="#fff" stroke="#08a878" stroke-width="2"><title>${p.date}: ${money(p.balance)}</title></circle>`).join('')}</svg><div class="chart-labels"><span>${points[0].date}</span><span>${points.at(-1)!.date}</span></div>`;}
function kpi(label:string,val:string,sub:string,icon:string,cls=''){return `<article class="kpi"><div class="kpi-top"><span>${label}</span><span class="kpi-icon">${icon}</span></div><strong class="${cls}">${val}</strong><small>${sub}</small></article>`;}
function tradeRow(t:Trade){const result=pnl(t);return `<tr><td>${new Date(t.date+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})}</td><td><b>${t.symbol}</b><small>${t.strategy||'—'} · ${t.setup||'No setup'}</small></td><td><span class="pill ${t.direction==='Long'?'positive':'neutral'}">${t.direction}</span></td><td><span class="pill ${t.status==='Closed'?'neutral':'warning'}">${t.status}</span></td><td>${money(result)}</td><td>${t.emotion||'—'}</td><td><button class="icon-btn" data-edit="${t.id}" title="Edit trade">✎</button> <button class="icon-btn danger-text" data-delete="${t.id}" title="Delete trade">×</button></td></tr>`;}
function empty(title:string,desc:string){return `<div class="empty-state"><div class="empty-graphic">⌁</div><b>${title}</b><span>${desc}</span><button class="btn primary" data-action="add">＋ Add your first trade</button></div>`;}
function overview(ts:Trade[]){const m=stats(ts),accountObj=state.accounts.find(a=>a.id===account)??state.accounts[0],curve=equity(ts,accountObj?.balance??0),bal=(accountObj?.balance??0)+m.net;const recent=[...ts].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5);return `<section class="welcome"><div><div class="eyebrow">${new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'})}</div><h1>Good trading starts with <em>good reflection.</em></h1><p>Every trade tells you something. Let’s make the next one count.</p></div><button class="btn primary" data-action="add">＋ Record a trade</button></section><section class="kpis">${kpi('Current balance',money(bal,accountObj?.currency),`${m.closed} closed trades`, '◉')}${kpi('Net profit / loss',money(m.net),`${m.closed?'Across selected period':'Ready when you are'}`,'↗',m.net>=0?'positive-text':'negative-text')}${kpi('Win rate',m.winRate===null?'—':`${m.winRate.toFixed(1)}%`,`${m.wins} wins · ${m.losses} losses`,'◎')}${kpi('Profit factor',m.profitFactor===null?'—':m.profitFactor.toFixed(2),m.profitFactor===null?'Needs winning and losing trades':'Gross wins ÷ gross losses','⌁')}${kpi('Expectancy',money(m.expectancy),`Average per closed trade`,'◌')}${kpi('Rule following',m.ruleRate===null?'—':`${m.ruleRate.toFixed(0)}%`,'Trades marked plan-following','✓')}</section><section class="grid-main"><article class="card chart-card"><div class="section-head"><div><h2>Equity curve</h2><p>Realized balance over your selected period</p></div><span class="chart-period">${m.closed?`${m.closed} trades`:'No trades yet'}</span></div>${chart(ts,accountObj?.balance??0)}</article><article class="card focus-card"><div class="section-head"><div><h2>Trading focus</h2><p>Build a consistent review habit</p></div><span class="spark">✳</span></div><div class="focus-number">${state.reviews.length}<small>reviews saved</small></div><div class="focus-line"><span>Account progress</span><b>${m.closed?money(m.net):'Awaiting first trade'}</b></div><div class="focus-track"><i style="width:${m.closed?Math.min(100,Math.max(8,m.winRate??8)):0}%"></i></div><button class="text-btn" data-page="Daily Reviews">Open daily review <span>→</span></button></article></section><section class="grid-bottom"><article class="card"><div class="section-head"><div><h2>Recent trades</h2><p>Your latest journal entries</p></div><button class="text-btn" data-page="Trade Journal">View journal →</button></div>${recent.length?`<div class="table-scroll"><table><thead><tr><th>Date</th><th>Instrument</th><th>Side</th><th>Status</th><th>Net P&L</th><th>Emotion</th><th></th></tr></thead><tbody>${recent.map(tradeRow).join('')}</tbody></table></div>`:empty('Your journal is ready','Add your first trade to see your story take shape.')}</article><article class="card side-note"><div class="section-head"><div><h2>Journal reminder</h2><p>Small reflections, lasting progress</p></div><span class="reminder-icon">✦</span></div><blockquote>“The goal is not to be right. The goal is to be disciplined.”</blockquote><div class="privacy-note"><span class="privacy-dot"></span><div><b>Your journal stays on this device</b><small>Private by design. Export a backup to transfer it.</small></div></div><button class="btn soft full" data-page="Settings & Backup">Manage your backup</button></article></section>`;}
function journal(ts:Trade[]){return `<section class="page-intro"><div><div class="eyebrow">YOUR RECORD, YOUR RULES</div><h1>Trade journal</h1><p>Capture the setup, the decision and what you learned.</p></div><button class="btn primary" data-action="add">＋ Add trade</button></section><article class="card"><div class="section-head"><div><h2>All trades <span class="count">${ts.length}</span></h2><p>Stored privately in this browser</p></div><div class="backup-actions"><button class="btn soft" data-action="csv-export">↓ Export Excel CSV</button><button class="btn soft" data-action="pdf-export">↓ Export PDF</button></div></div>${ts.length?`<div class="table-scroll"><table><thead><tr><th>Date</th><th>Instrument</th><th>Side</th><th>Status</th><th>Net P&L</th><th>Emotion</th><th>Actions</th></tr></thead><tbody>${[...ts].sort((a,b)=>b.date.localeCompare(a.date)).map(tradeRow).join('')}</tbody></table></div>`:empty('No trades in this view','Add a trade or adjust your account and date filters.')}</article>`;}
function calendar(ts:Trade[]){const now=new Date(),year=now.getFullYear(),month=now.getMonth(),first=new Date(year,month,1),offset=(first.getDay()+6)%7,days=new Date(year,month+1,0).getDate(),map=new Map<string,number>();ts.filter(t=>t.status==='Closed').forEach(t=>map.set(t.date,(map.get(t.date)??0)+(pnl(t)??0)));const cells=Array.from({length:offset},()=>'<div class="day blank"></div>');for(let d=1;d<=days;d++){const key=`${year}-${String(month+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`,v=map.get(key);cells.push(`<button class="day ${v===undefined?'':v>0?'day-win':v<0?'day-loss':'day-flat'}" data-date="${key}"><span>${d}</span>${v===undefined?'':`<b>${money(v)}</b>`}</button>`);}const totals=[...map.values()],sum=totals.reduce((a,b)=>a+b,0);return `<section class="page-intro"><div><div class="eyebrow">SEE THE BIGGER PICTURE</div><h1>Trading calendar</h1><p>Your daily results, drawn from your actual closed trades.</p></div><button class="btn soft" data-action="today">Today</button></section><div class="kpis">${kpi('Month net P&L',money(sum),`${totals.length} trading days`,'↗',sum>=0?'positive-text':'negative-text')}${kpi('Profitable days',totals.length?`${totals.filter(v=>v>0).length}/${totals.length}`:'—','Days with positive net P&L','◉')}${kpi('Best day',totals.length?money(Math.max(...totals)):'—','This month','↑')}${kpi('Worst day',totals.length?money(Math.min(...totals)):'—','This month','↓')}</div><article class="card calendar-card"><div class="section-head"><div><h2>${now.toLocaleDateString(undefined,{month:'long',year:'numeric'})}</h2><p>Tap a date to record a trade</p></div><div class="legend"><span><i class="lg-win"></i>Profit</span><span><i class="lg-loss"></i>Loss</span><span><i></i>No trades</span></div></div><div class="calendar-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(x=>`<div class="weekday">${x}</div>`).join('')}${cells.join('')}</div></article>`;}
function strategies(ts:Trade[]){const keys=[...new Set(ts.map(t=>t.setup||'Uncategorized'))];return `<section class="page-intro"><div><div class="eyebrow">PATTERNS, NOT PROMISES</div><h1>Strategies & setups</h1><p>Compare your recorded outcomes. Metrics describe history, not future results.</p></div><button class="btn primary" data-action="add">＋ Record a trade</button></section><article class="card">${keys.length?`<div class="strategy-grid">${keys.map(name=>{const m=stats(ts.filter(t=>(t.setup||'Uncategorized')===name));return `<div class="strategy-card"><div class="strategy-symbol">⌁</div><h3>${name}</h3><p>${m.closed} closed trades${m.closed<10?' · Early sample':''}</p><div class="strategy-stat"><span>Net P&L</span><b class="${m.net>=0?'positive-text':'negative-text'}">${money(m.net)}</b></div><div class="strategy-stat"><span>Win rate</span><b>${m.winRate===null?'—':m.winRate.toFixed(1)+'%'}</b></div><div class="strategy-stat"><span>Expectancy</span><b>${money(m.expectancy)}</b></div><div class="strategy-stat"><span>Profit factor</span><b>${m.profitFactor===null?'—':m.profitFactor.toFixed(2)}</b></div></div>`}).join('')}</div>`:empty('No strategy data yet','Give a strategy a name when logging a trade to compare outcomes.')}</article>`;}
function analytics(ts:Trade[]){const m=stats(ts),days=new Map<string,number>();ts.filter(t=>t.status==='Closed').forEach(t=>days.set(t.date,(days.get(t.date)??0)+(pnl(t)??0)));const sorted=[...days.entries()].sort((a,b)=>a[0].localeCompare(b[0]));return `<section class="page-intro"><div><div class="eyebrow">DATA-LED REFLECTION</div><h1>Performance analytics</h1><p>Explore the outcomes of trades in the selected account and period.</p></div></section><section class="kpis">${kpi('Closed trades',String(m.closed),'Open positions excluded','▤')}${kpi('Average win',money(m.avgWin),`${m.wins} winning trades`,'↑','positive-text')}${kpi('Average loss',money(m.avgLoss),`${m.losses} losing trades`,'↓','negative-text')}${kpi('Average realized R',m.averageR===null?'—':`${m.averageR.toFixed(2)}R`,'Requires valid stop-loss data','⌁')}</section><article class="card chart-card"><div class="section-head"><div><h2>Equity curve</h2><p>Selected-period realized outcomes · no open-trade estimates</p></div></div>${chart(ts)}</article><section class="grid-bottom"><article class="card"><h2>Daily net results</h2><p class="muted">Daily P&L · ${sorted.length} trading days</p>${sorted.length?sorted.slice(-10).reverse().map(([d,v])=>`<div class="bar-row"><span>${new Date(d+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric'})}</span><div class="bar-track"><i class="${v<0?'loss-bar':''}" style="width:${Math.max(4,Math.abs(v)/(Math.max(1,...sorted.map(x=>Math.abs(x[1]))))*100)}%"></i></div><b class="${v>=0?'positive-text':'negative-text'}">${money(v)}</b></div>`).join(''):empty('Not enough data yet','Closed trades create the daily summary.')}</article><article class="card"><h2>Outcome mix</h2><p class="muted">Closed trades · break-even included in denominator</p><div class="outcome-ring" style="--win:${m.winRate??0}%"><div><b>${m.winRate===null?'—':m.winRate.toFixed(0)+'%'}</b><small>win rate</small></div></div><div class="ring-legend"><span><i class="lg-win"></i>Wins <b>${m.wins}</b></span><span><i class="lg-loss"></i>Losses <b>${m.losses}</b></span><span><i class="lg-flat"></i>Breakeven <b>${m.closed-m.wins-m.losses}</b></span></div></article></section>`;}
function reviews(){return `<section class="page-intro"><div><div class="eyebrow">PROCESS OVER OUTCOME</div><h1>Daily reviews</h1><p>A few honest lines today can improve the next session.</p></div><button class="btn primary" data-action="review">＋ New review</button></section><div class="review-layout"><article class="card review-form"><div class="section-head"><div><h2>Daily reflection</h2><p>Saved only on this device</p></div><span class="reminder-icon">✦</span></div><label>Date<input id="review-date" type="date" value="${new Date().toISOString().slice(0,10)}"></label><label>Pre-market plan<textarea id="review-plan" rows="3" placeholder="What is your plan? Which setups deserve your attention?"></textarea></label><label>Post-market review<textarea id="review-review" rows="3" placeholder="What did you do well? Where did you drift from your plan?"></textarea></label><label>Key lesson<textarea id="review-lesson" rows="2" placeholder="One thing to carry into tomorrow..."></textarea></label><button class="btn primary" data-action="save-review">Save review</button></article><article class="card"><h2>Recent reflections</h2><p class="muted">Your review history</p>${state.reviews.length?[...state.reviews].sort((a,b)=>b.date.localeCompare(a.date)).map(r=>`<div class="review-item"><b>${new Date(r.date+'T12:00:00').toLocaleDateString(undefined,{month:'long',day:'numeric',year:'numeric'})}</b>${r.plan?`<p><small>Plan</small><br>${escapeHTML(r.plan)}</p>`:''}${r.review?`<p><small>Reflection</small><br>${escapeHTML(r.review)}</p>`:''}${r.lesson?`<p><small>Lesson</small><br>${escapeHTML(r.lesson)}</p>`:''}</div>`).join(''):empty('No reflections yet','Your daily reviews will appear here.')}</article></div>`;}
function risk(ts:Trade[]){const accountObj=state.accounts.find(a=>a.id===account)??state.accounts[0],today=new Date().toISOString().slice(0,10),todayPnl=ts.filter(t=>t.date===today&&t.status==='Closed').reduce((a,t)=>a+(pnl(t)??0),0),currency=positionCurrency||accountObj?.currency||state.settings.currency,pairs=['EUR/USD','GBP/USD','AUD/USD','NZD/USD','USD/JPY','USD/CHF','USD/CAD','EUR/GBP','EUR/JPY','GBP/JPY','AUD/JPY','EUR/CHF','EUR/AUD','EUR/CAD'],pair=pairs.includes(positionPair)?positionPair:'EUR/USD',quote=pair.split('/')[1],conversionNeeded=quote!==currency;return `<section class="page-intro"><div><div class="eyebrow">KNOW YOUR EXPOSURE</div><h1>Risk management</h1><p>Size a position from your account, chosen risk and stop distance.</p></div></section><section class="risk-layout"><article class="card position-card"><div class="position-head"><span class="position-icon">▥</span><div><h2>Position size calculator</h2><p>Results update as you adjust the inputs.</p></div><button class="btn soft risk-reset" data-action="risk-reset">Reset</button></div><div class="position-fields"><label>Account currency<select id="position-currency">${['USD','EUR','GBP','INR','JPY','CAD','AUD','CHF','NZD'].map(c=>`<option ${c===currency?'selected':''}>${c}</option>`).join('')}</select></label><label>Currency pair<select id="position-pair">${pairs.map(p=>`<option ${p===pair?'selected':''}>${p}</option>`).join('')}</select></label><label class="field-wide">Account balance (${currency})<input id="position-balance" type="number" min="0" step="any" value="${positionBalance??accountObj?.balance??10000}"></label><div class="field-wide risk-control"><label for="position-risk">${positionRiskMode==='percent'?'Risk percentage':'Fixed risk amount ('+currency+')'}</label><div class="risk-control-row"><input id="position-risk" type="number" min="0" step="any" value="${positionRiskValue}"><div class="risk-mode"><button type="button" data-risk-mode="percent" class="${positionRiskMode==='percent'?'selected':''}">%</button><button type="button" data-risk-mode="fixed" class="${positionRiskMode==='fixed'?'selected':''}">${currency==='USD'?'$':currency}</button></div></div>${positionRiskMode==='percent'?`<div class="risk-presets">${[0.5,1,2,3,5].map(v=>`<button type="button" data-risk-preset="${v}" class="${positionRiskValue===v?'selected':''}">${v}%</button>`).join('')}</div>`:''}<small id="risk-amount-hint" class="field-hint">Risk amount: —</small></div><label>Stop-loss distance (pips)<input id="position-stop" type="number" min="0" step="any" value="${positionStopPips}"><small class="field-hint">Enter the distance from entry to stop, in standard pips.</small></label><label>Units per lot<input id="position-units" type="number" min="1" step="1" value="${positionUnitsPerLot}"><small class="field-hint">Check your broker’s contract size.</small></label><label class="field-wide">${quote} → ${currency} conversion rate<input id="position-conversion" type="number" min="0" step="any" placeholder="Enter current rate" value="${conversionNeeded?(positionConversionRate??''):1}" ${conversionNeeded?'':'disabled'}><small class="field-hint">${conversionNeeded?`Enter how many ${currency} one ${quote} is worth. Use your broker’s current rate.`:'No conversion needed; pair quote currency matches account currency.'}</small></label></div><section class="position-results"><div class="results-caption">CALCULATED POSITION</div><div class="result-cards"><div class="position-result"><span>Risk amount</span><b id="position-risk-result">—</b><small id="position-risk-percent-result">of balance</small></div><div class="position-result featured"><span>Position size</span><b id="position-lots-result">—</b><small>lots · rounded down to 0.01</small></div><div class="position-result"><span>Units</span><b id="position-units-result">—</b><small>base currency units</small></div></div><div class="pip-summary"><span>Pip value / lot <b id="pip-lot-result">—</b></span><span>Total pip value <b id="pip-total-result">—</b></span></div><p id="position-calc-message" class="calc-message">Enter a valid balance, risk and stop distance.</p></section><p class="calc-disclaimer">ⓘ Forex estimate using standard pip conventions. Verify contract size, pip value, conversion rate and lot step with your broker.</p></article><aside class="risk-aside"><article class="card how-card"><h2>How to use</h2><ol><li><b>Enter account details</b><span>Choose your account currency and balance.</span></li><li><b>Set your risk</b><span>Use a percentage of balance or a fixed cash amount.</span></li><li><b>Select pair and stop</b><span>Choose the pair and enter the stop distance in pips.</span></li><li><b>Review position size</b><span>Use the rounded lot size to keep planned risk within your limit.</span></li></ol><div class="risk-guide"><b>RISK GUIDE</b><span>0.5–1% per trade <strong class="conservative">Conservative</strong></span><span>1–2% per trade <strong class="moderate">Moderate</strong></span><span>2–5% per trade <strong class="aggressive">Aggressive</strong></span><small>Illustrative education only, not a recommendation.</small></div></article><article class="card guardrail-card"><h2>Daily guardrails</h2><p class="muted">Informational limits; they do not prevent trading.</p><label>Maximum daily loss (${state.settings.currency})<input id="daily-limit" type="number" min="0" step="any" value="${state.settings.dailyLossLimit||''}" placeholder="Set a personal limit"></label><div class="privacy-note"><span class="privacy-dot"></span><div><b>Today's realized P&L</b><small class="${todayPnl>=0?'positive-text':'negative-text'}">${money(todayPnl)}</small></div></div>${state.settings.dailyLossLimit?`<div class="limit-state ${todayPnl<=-state.settings.dailyLossLimit?'limit-hit':''}">${todayPnl<=-state.settings.dailyLossLimit?'Daily loss limit reached':'Within your configured daily limit'}</div>`:'<p class="muted">Add a daily loss limit to see your progress.</p>'}</article></aside></section>`;}function settings(){const bytes=new Blob([JSON.stringify(state)]).size;return `<section class="page-intro"><div><div class="eyebrow">YOUR DATA, YOUR DEVICE</div><h1>Settings & backup</h1><p>Your journal is saved locally and syncs to your private Google Sheet when you are connected.</p></div></section><div class="settings-grid"><article class="card"><h2>Preferences</h2><label>Display theme<select id="theme"><option value="light" ${state.settings.theme==='light'?'selected':''}>Light</option><option value="dark" ${state.settings.theme==='dark'?'selected':''}>Dark</option></select></label><label>Currency<select id="currency">${['USD','EUR','GBP','INR','JPY','CAD','AUD'].map(c=>`<option ${c===state.settings.currency?'selected':''}>${c}</option>`).join('')}</select></label><div class="privacy-note"><span class="privacy-dot"></span><div><b>Local browser storage</b><small id="saved">${state.lastBackup?'Last backup: '+new Date(state.lastBackup).toLocaleDateString():'Saved on this device'} · ${(bytes/1024).toFixed(1)} KB used</small></div></div><p class="muted small">Clearing browser or site data may erase your journal. Export backups regularly and transfer them manually between devices.</p></article><article class="card"><h2>Backup & restore</h2><p class="muted">A JSON backup includes trades, account settings and daily reviews. It is stored locally and, when connected, in your private Google Sheet.</p><div class="backup-actions"><button class="btn primary" data-action="json-export">↓ Export full backup</button><label class="btn soft file-button">↑ Import backup<input id="json-file" type="file" accept="application/json,.json" hidden></label></div><div class="backup-actions"><button class="btn soft" data-action="csv-export">Export Excel CSV</button><button class="btn soft" data-action="pdf-export">Export PDF report</button></div><button class="text-btn" data-action="csv-import">Import trades from CSV →</button><p class="muted small">Google sync runs after sign-in; JSON backup remains available for recovery and manual transfer.</p></article><article class="card sync-card"><h2>Google Sheets sync</h2><p class="muted">Signed in as <b>${escapeHTML(signedInEmail)}</b>. Use the same Google account on each device.</p><button class="btn soft" data-action="google-signout">Sign out</button><p class="muted">You can reconnect or switch accounts from the sign-in screen.</p><p class="muted small">Google sign-in is configured for this Trading Journal app. Use the same Google account on each device.</p>${readSheetsConfig().spreadsheetId?`<a class="text-btn" href="https://docs.google.com/spreadsheets/d/${encodeURIComponent(readSheetsConfig().spreadsheetId)}/edit" target="_blank" rel="noreferrer">Open your private Trading Journal spreadsheet ↗</a>`:`<p class="muted small">Your private spreadsheet is created automatically when you sign in.</p>`}<button class="btn primary" data-action="google-connect">${sheetsConnected?'Sync now':'Connect & sync'}</button><p class="muted small">The sheet must remain private. Google authorization is requested only when needed; tokens are kept in memory and are not stored in this browser.</p></article><article class="card account-card"><h2>Trading accounts</h2><p class="muted">Separate journal entries by account. No currency conversion is applied to combined views.</p>${state.accounts.map(a=>`<div class="account-item"><span class="account-avatar">${a.name.slice(0,1).toUpperCase()}</span><div class="account-details"><b>${escapeHTML(a.name)}</b><small>${a.currency} · Starting balance ${money(a.balance,a.currency)}</small><small class="account-subtitle">${escapeHTML([a.broker,a.accountType].filter(Boolean).join(' · ')||'Trading account')}</small></div><div class="account-controls"><button class="btn soft" data-account-edit="${a.id}">Edit</button><button class="btn soft account-delete" data-account-delete="${a.id}">Delete</button></div></div>`).join('')}<button class="btn soft" data-action="account-add">＋ Add account</button></article></div>`;}
function escapeHTML(s:string){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));}
