function app(){if(!signedInEmail){loginGate();return;}document.documentElement.dataset.theme=state.settings.theme;if(account==='all'&&new Set(state.accounts.map(a=>a.currency)).size>1)account=state.accounts[0]?.id??'default';const ts=selectedTrades();const content=page==='Overview'?overview(ts):page==='Trade Journal'?journal(ts):page==='Trading Calendar'?calendar(ts):page==='Strategies & Setups'?strategies(ts):page==='Performance Analytics'?analytics(ts):page==='Daily Reviews'?reviews():page==='Risk Management'?risk(ts):settings();const accountOptions=state.accounts.map(a=>`<option value="${a.id}" ${account===a.id?'selected':''}>${escapeHTML(a.name)} · ${a.currency}</option>`).join('');$('#app').innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="brand"><img class="brand-mark" src="${import.meta.env.BASE_URL}icon.svg" alt=""><div><b>Trading Journal</b><small>TRADE · REVIEW · GROW</small></div></div><div class="nav-label">WORKSPACE</div><nav>${nav.map(([n,icon])=>`<button class="nav-item ${page===n?'active':''}" data-page="${n}"><span class="nav-icon">${icon}</span>${n}${n==='Trade Journal'&&state.trades.length?`<small class="nav-count">${state.trades.length}</small>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="privacy-box"><div class="privacy-heading"><span class="privacy-dot"></span><b>Private & local</b></div><p>Your journal is available on your devices when Google sync is connected.</p><button data-page="Settings & Backup">Backup data <span>→</span></button></div><div class="profile-row"><div class="profile-avatar">${(state.accounts[0]?.name||'T').slice(0,1).toUpperCase()}</div><div><b>${escapeHTML(state.accounts[0]?.name||'My account')}</b><small>Personal journal</small></div><span class="profile-more">···</span></div></div></aside><button class="sidebar-scrim" data-action="close-menu" aria-label="Close navigation"></button><main class="main"><header class="topbar"><div class="breadcrumb"><span>Workspace</span><i>/</i><b>${title()}</b></div><div class="top-actions"><label class="filter-label account-filter"><span>Account</span><select id="account-filter"><option value="all">All accounts</option>${accountOptions}</select></label><label class="filter-label period-filter"><span>Period</span><select id="range-filter"><option value="all" ${range==='all'?'selected':''}>All time</option><option value="30" ${range==='30'?'selected':''}>Last 30 days</option><option value="90" ${range==='90'?'selected':''}>Last 90 days</option><option value="365" ${range==='365'?'selected':''}>Last year</option></select></label><button class="theme-toggle" data-action="theme" title="Toggle theme">${state.settings.theme==='light'?'☾':'☀'}</button><button class="btn primary top-add" data-action="add">＋ <span>Add trade</span></button></div><button class="mobile-menu" data-action="menu" aria-label="Open navigation">☰</button></header><div class="page-content"><label class="mobile-account-bar"><span>ACTIVE ACCOUNT</span><select id="mobile-account-filter"><option value="all">All accounts</option>${accountOptions}</select></label>${content}<footer><span id="saved">● Data saved locally</span><span>Trading Journal <i>·</i> Trade with a plan.</span></footer></div></main><nav class="mobile-nav" aria-label="Primary navigation">${[['Overview','◫'],['Trade Journal','▤'],['Trading Calendar','▦'],['Performance Analytics','⌁']].map(([n,ic])=>`<button class="${page===n?'active':''}" data-page="${n}"><span>${ic}</span><small>${n==='Trade Journal'?'Trades':n==='Trading Calendar'?'Calendar':n==='Performance Analytics'?'Analytics':'Home'}</small></button>`).join('')}</nav><div id="toast" role="status" class="toast"></div><div id="modal-root"></div></div>`;bind();}
function showForm(t?:Trade){editing=t?.id??null;const x=t??{date:new Date().toISOString().slice(0,10),symbol:'',direction:'Long',status:'Closed',entry:'',exit:'',stop:'',target:'',quantity:1,multiplier:1,fees:0,manualNet:'',setup:'',strategy:'',emotion:'',rules:true,notes:'',accountId:state.accounts[0]?.id??'default'} as unknown as Trade;const estimated=(Number(x.exit||0)-Number(x.entry||0))*Number(x.quantity||1)*Number(x.multiplier||1)*(x.direction==='Long'?1:-1)-Number(x.fees||0);$('#modal-root').innerHTML=`<div class="modal-backdrop" data-action="backdrop"><form class="trade-modal" id="trade-form"><div class="modal-head"><div><div class="eyebrow">${t?'REVIEW YOUR RECORD':'CAPTURE THE DETAILS'}</div><h2>${t?'Edit trade':'Add a trade'}</h2></div><button type="button" class="icon-btn modal-close" data-action="close">×</button></div><div class="form-scroll"><div class="form-section-title">Trade information</div><div class="form-grid"><label>Date<input name="date" type="date" value="${x.date}" required></label><label>Instrument<input name="symbol" placeholder="e.g. XAUUSD" value="${escapeHTML(x.symbol)}" required></label><label>Side<select name="direction"><option ${x.direction==='Long'?'selected':''}>Long</option><option ${x.direction==='Short'?'selected':''}>Short</option></select></label><label>Status<select name="status"><option ${x.status==='Closed'?'selected':''}>Closed</option><option ${x.status==='Open'?'selected':''}>Open</option></select></label><label>Account<select name="accountId">${state.accounts.map(a=>`<option value="${a.id}" ${x.accountId===a.id?'selected':''}>${escapeHTML(a.name)}</option>`).join('')}</select></label><label>Setup<input name="setup" placeholder="e.g. Pullback" value="${escapeHTML(x.setup)}"></label><label>Emotion<input name="emotion" placeholder="e.g. Calm" value="${escapeHTML(x.emotion)}"></label></div><div class="form-section-title">Price levels & position size</div><div class="form-grid"><label>Entry price<input name="entry" type="number" step="any" value="${x.entry}" required></label><label>Exit price<input name="exit" type="number" step="any" value="${x.exit??''}" placeholder="Required to calculate a closed trade"></label><label>Stop loss<input name="stop" type="number" step="any" value="${x.stop??''}"></label><label>Take profit<input name="target" type="number" step="any" value="${x.target??''}"></label><label>Quantity / lots<input name="quantity" type="number" step="any" min="0" value="${x.quantity}" required></label></div><div class="estimate-box"><span>Calculated net P&L preview</span><b id="pnl-preview">${x.status==='Closed'?money(estimated):'Open trade · excluded from realized metrics'}</b><small>Generic price-difference estimate. Broker contract specs and currency conversion may differ.</small></div><div class="form-section-title">Psychology & review</div><div class="form-grid"><label>Followed my rules?<select name="rules"><option value="yes" ${x.rules?'selected':''}>Yes</option><option value="no" ${!x.rules?'selected':''}>No</option></select></label><label class="span-two">Notes & lessons<textarea name="notes" rows="3" placeholder="What did you notice? What will you learn from this trade?">${escapeHTML(x.notes)}</textarea></label></div><p class="form-hint">For a Long trade, stop loss is usually below entry and target above. For a Short trade, the reverse. Please check your levels; values are kept as entered.</p></div><div class="modal-actions"><button type="button" class="btn soft" data-action="close">Cancel</button><button type="submit" class="btn primary">${t?'Save changes':'Save trade'}</button></div></form></div>`;const modal=$('#modal-root');modal.querySelectorAll('[data-action=close]').forEach(b=>b.addEventListener('click',()=>modal.innerHTML=''));modal.querySelector('.modal-backdrop')?.addEventListener('click',e=>{if(e.target===e.currentTarget)modal.innerHTML='';});const form=$('#trade-form') as HTMLFormElement;form.addEventListener('input',()=>{const d=new FormData(form),e=Number(d.get('entry')),ex=Number(d.get('exit')),q=Number(d.get('quantity')),mul=Number(x.multiplier||1),fees=Number(d.get('fees')||0),long=d.get('direction')==='Long';$('#pnl-preview').textContent=d.get('status')==='Closed'&&Number.isFinite(ex)?money((long?ex-e:e-ex)*q*mul-fees):'Open trade · excluded from realized metrics';});form.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(form),entry=Number(d.get('entry')),exit=d.get('exit')?Number(d.get('exit')):null,stop=d.get('stop')?Number(d.get('stop')):null,target=d.get('target')?Number(d.get('target')):null,direction=d.get('direction') as Trade['direction'];if(d.get('status')==='Closed'&&exit===null){notify('Add an exit price or mark the trade open.');return;}if(!Number.isFinite(entry)||Number(d.get('quantity'))<=0){notify('Check entry, quantity and multiplier values.');return;}if((direction==='Long'&&((stop!==null&&stop>=entry)||(target!==null&&target<=entry)))||(direction==='Short'&&((stop!==null&&stop<=entry)||(target!==null&&target>=entry)))){if(!confirm('These stop-loss or take-profit levels look unusual for the selected direction. Save them exactly as entered?'))return;}const item:Trade={id:editing??crypto.randomUUID(),date:String(d.get('date')),symbol:String(d.get('symbol')).trim().toUpperCase(),direction,status:d.get('status') as Trade['status'],entry,exit,stop,target,quantity:Number(d.get('quantity')),multiplier:t?.multiplier??1,fees:t?.fees??0,manualNet:t?.manualNet??null,setup:String(d.get('setup')),strategy:'',emotion:String(d.get('emotion')),rules:d.get('rules')==='yes',notes:String(d.get('notes')),accountId:String(d.get('accountId')),createdAt:new Date().toISOString()};if(editing)state.trades=state.trades.map(a=>a.id===editing?item:a);else state.trades.unshift(item);persist();$('#modal-root').innerHTML='';notify(editing?'Trade updated':'Trade saved locally');app();});}
function bind(){document.querySelectorAll<HTMLElement>('[data-page]').forEach(el=>el.onclick=()=>{page=el.dataset.page!;document.querySelector('.sidebar')?.classList.remove('mobile-open');app();});document.querySelectorAll<HTMLElement>('[data-action]').forEach(el=>el.onclick=()=>action(el.dataset.action!,el));document.querySelectorAll<HTMLElement>('[data-account-edit]').forEach(el=>el.onclick=()=>{const existing=state.accounts.find(a=>a.id===el.dataset.accountEdit);if(existing)showAccountForm(existing);});document.querySelectorAll<HTMLElement>('[data-account-delete]').forEach(el=>el.onclick=()=>deleteAccount(el.dataset.accountDelete!));document.querySelectorAll<HTMLElement>('[data-edit]').forEach(el=>el.onclick=()=>{const t=state.trades.find(x=>x.id===el.dataset.edit);if(t)showForm(t);});document.querySelectorAll<HTMLElement>('[data-delete]').forEach(el=>el.onclick=()=>{if(confirm('Delete this trade? This cannot be undone.')){deletedTradeIds.add(el.dataset.delete!);localStorage.setItem(userStorageKey('google-deleted-trades'),JSON.stringify([...deletedTradeIds]));state.trades=state.trades.filter(t=>t.id!==el.dataset.delete);persist();app();notify('Trade deleted');}});$('#account-filter')?.addEventListener('change',e=>{account=(e.target as HTMLSelectElement).value;app();});$('#mobile-account-filter')?.addEventListener('change',e=>{account=(e.target as HTMLSelectElement).value;app();});$('#range-filter')?.addEventListener('change',e=>{range=(e.target as HTMLSelectElement).value;app();});$('#theme')?.addEventListener('change',e=>{state.settings.theme=(e.target as HTMLSelectElement).value as 'light'|'dark';persist();app();});$('#currency')?.addEventListener('change',e=>{state.settings.currency=(e.target as HTMLSelectElement).value;persist();app();});$('#daily-limit')?.addEventListener('change',e=>{state.settings.dailyLossLimit=Number((e.target as HTMLInputElement).value)||0;persist();app();});$('#json-file')?.addEventListener('change',e=>importJSON(e));['#position-risk','#position-balance','#position-stop','#position-units','#position-conversion'].forEach(selector=>document.querySelector(selector)?.addEventListener('input',calcRisk));$('#position-currency')?.addEventListener('change',()=>{positionCurrency=($('#position-currency') as HTMLSelectElement).value;app();});$('#position-pair')?.addEventListener('change',()=>{positionPair=($('#position-pair') as HTMLSelectElement).value;app();});document.querySelectorAll<HTMLButtonElement>('[data-risk-mode]').forEach(btn=>btn.onclick=()=>{positionRiskMode=btn.dataset.riskMode as 'percent'|'fixed';app();});document.querySelectorAll<HTMLButtonElement>('[data-risk-preset]').forEach(btn=>btn.onclick=()=>{positionRiskMode='percent';positionRiskValue=Number(btn.dataset.riskPreset);app();});calcRisk();document.querySelectorAll<HTMLElement>('[data-date]').forEach(el=>el.onclick=()=>{page='Trade Journal';app();showForm();(document.querySelector('[name=date]') as HTMLInputElement).value=el.dataset.date!;});}
function calcRisk(){if(!document.querySelector('#position-risk'))return;const balanceInput=$('#position-balance') as HTMLInputElement,riskInput=$('#position-risk') as HTMLInputElement,stopInput=$('#position-stop') as HTMLInputElement,unitsInput=$('#position-units') as HTMLInputElement,currencyInput=$('#position-currency') as HTMLSelectElement,pairInput=$('#position-pair') as HTMLSelectElement,conversionInput=$('#position-conversion') as HTMLInputElement;positionBalance=Number(balanceInput.value);positionRiskValue=Number(riskInput.value);positionStopPips=Number(stopInput.value);positionUnitsPerLot=Number(unitsInput.value);positionCurrency=currencyInput.value;positionPair=pairInput.value;positionConversionRate=conversionInput.disabled?1:(conversionInput.value===''?null:Number(conversionInput.value));const currency=positionCurrency,quote=positionPair.split('/')[1],rate=quote===currency?1:positionConversionRate,pipSize=quote==='JPY'?0.01:0.0001,riskAmount=positionRiskMode==='percent'?positionBalance*positionRiskValue/100:positionRiskValue;const show=(selector:string,value:string)=>{const el=document.querySelector<HTMLElement>(selector);if(el)el.textContent=value;};const fmt=(value:number)=>new Intl.NumberFormat(undefined,{style:'currency',currency,maximumFractionDigits:2}).format(value);show('#risk-amount-hint',Number.isFinite(riskAmount)&&riskAmount>0?`Risk amount: ${fmt(riskAmount)}${positionRiskMode==='percent'?` (${positionRiskValue}% of balance)`:''}`:'Enter a positive risk amount.');const msg=document.querySelector<HTMLElement>('#position-calc-message');const outputs=['#position-risk-result','#position-risk-percent-result','#position-lots-result','#position-units-result','#pip-lot-result','#pip-total-result'];if(positionBalance<=0||positionRiskValue<=0||positionStopPips<=0||positionUnitsPerLot<=0||!Number.isFinite(positionBalance)||!Number.isFinite(positionRiskValue)||!Number.isFinite(positionStopPips)||!Number.isFinite(positionUnitsPerLot)||rate===null||!Number.isFinite(rate)||rate<=0){outputs.forEach(s=>show(s,'—'));if(msg)msg.textContent=rate===null?'Enter the current quote-to-account conversion rate.':'Enter a positive balance, risk, stop distance and units per lot.';return;}const pipValuePerLot=positionUnitsPerLot*pipSize*rate,rawLots=riskAmount/(positionStopPips*pipValuePerLot),lots=Math.floor((rawLots+1e-10)*100)/100,units=Math.floor(lots*positionUnitsPerLot),actualRisk=lots*positionStopPips*pipValuePerLot;show('#position-risk-result',fmt(riskAmount));show('#position-risk-percent-result',`${(riskAmount/positionBalance*100).toFixed(2)}% of balance`);show('#position-lots-result',lots.toFixed(2));show('#position-units-result',units.toLocaleString());show('#pip-lot-result',`${fmt(pipValuePerLot)} / pip`);show('#pip-total-result',`${fmt(lots*pipValuePerLot)} / pip`);if(msg)msg.textContent=lots>0?`Estimated risk at rounded size: ${fmt(actualRisk)}${actualRisk<riskAmount?' · below your selected limit':''}`:'Risk amount is below the minimum 0.01 lot size for this stop distance.';}
function signOut(){clearTimeout(syncTimer);clearTimeout(cloudPollTimer);clearGoogleAuthorization();localStorage.removeItem(AUTH_EMAIL_KEY);signedInEmail='';googleName='';sheetsConnected=false;state=initial;account='all';deletedTradeIds.clear();app();}
function action(a:string,el:HTMLElement){if(a==='google-connect'){if(sheetsConnected)void syncSheets(true);else void connectGoogleSheets();return;}if(a==='google-signout'){signOut();return;}if(a==='risk-reset'){positionRiskMode='percent';positionRiskValue=1;positionStopPips=50;positionBalance=null;positionCurrency='';positionPair='EUR/USD';positionUnitsPerLot=100000;positionConversionRate=null;app();return;}if(a==='add')showForm();if(a==='close')$('#modal-root').innerHTML='';if(a==='backdrop'&&el===event?.target)$('#modal-root').innerHTML='';if(a==='theme'){state.settings.theme=state.settings.theme==='light'?'dark':'light';persist();app();}if(a==='menu')document.querySelector('.sidebar')?.classList.toggle('mobile-open');if(a==='close-menu')document.querySelector('.sidebar')?.classList.remove('mobile-open');if(a==='json-export'){const blob=new Blob([backup(state)],{type:'application/json'});download(blob,`trading-journal-backup-${new Date().toISOString().slice(0,10)}.json`);state.lastBackup=new Date().toISOString();persist();notify('Backup downloaded');}if(a==='csv-export')exportCSV(selectedTrades());if(a==='pdf-export')exportPDF(selectedTrades());if(a==='csv-import')csvImport();if(a==='account-add')showAccountForm();if(a==='account-edit'){const existing=state.accounts.find(x=>x.id===el.dataset.id);if(existing)showAccountForm(existing);}if(a==='account-delete')deleteAccount(el.dataset.id||'');if(a==='review'){page='Daily Reviews';app();}if(a==='save-review')saveReview();}
function download(blob:Blob,name:string){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function exportCSV(ts:Trade[]){const fields:[string,string][]=[['Date','date'],['Symbol','symbol'],['Direction','direction'],['Status','status'],['Account','account'],['Entry Price','entry'],['Exit Price','exit'],['Stop Loss','stop'],['Take Profit','target'],['Quantity / Lots','quantity'],['Setup','setup'],['Emotion','emotion'],['Followed Rules','rules'],['Net P&L','netPnl'],['Notes','notes']];const q=(v:unknown)=>`"${String(v??'').replaceAll('"','""')}"`;const lines=[fields.map(([label])=>q(label)).join(','),...ts.map(t=>fields.map(([,key])=>{const accountName=state.accounts.find(a=>a.id===t.accountId)?.name??'';const value=key==='netPnl'?pnl(t):key==='account'?accountName:(t as unknown as Record<string,unknown>)[key];return q(value);}).join(','))];download(new Blob(['\ufeff'+lines.join('\r\n')],{type:'text/csv;charset=utf-8'}),`trading-journal-trades-${new Date().toISOString().slice(0,10)}.csv`);notify('Excel-compatible CSV downloaded');}
function exportPDF(ts:Trade[]){const reportWindow=window.open('','_blank');if(!reportWindow){notify('Allow pop-ups for this site to create the PDF report.');return;}const m=stats(ts),selectedAccount=account==='all'?'All accounts':state.accounts.find(a=>a.id===account)?.name??'Selected account',sorted=[...ts].sort((a,b)=>a.date.localeCompare(b.date)),rows=sorted.map(t=>{const result=pnl(t),note=escapeHTML(t.notes||'—');return `<tr><td>${escapeHTML(t.date)}</td><td><b>${escapeHTML(t.symbol)}</b></td><td>${t.direction}</td><td>${t.status}</td><td>${t.entry}</td><td>${t.exit??'—'}</td><td>${t.stop??'—'}</td><td>${t.target??'—'}</td><td>${t.quantity}</td><td>${escapeHTML(t.setup||'—')}</td><td>${escapeHTML(t.emotion||'—')}</td><td class="${t.rules?'yes':'no'}">${t.rules?'Yes':'No'}</td><td class="pnl ${result===null?'':result>=0?'up':'down'}">${result===null?'Open':money(result)}</td><td class="notes">${note}</td></tr>`}).join(''),titleDate=new Date().toLocaleDateString(undefined,{year:'numeric',month:'long',day:'numeric'}),rate=m.winRate===null?'—':`${m.winRate.toFixed(1)}%`,factor=m.profitFactor===null?'—':m.profitFactor.toFixed(2);reportWindow.document.open();reportWindow.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Trading Journal Report</title><style>@page{size:A4 landscape;margin:12mm}*{box-sizing:border-box}body{font:10px/1.45 Arial,sans-serif;color:#18312c;margin:0}.head{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:3px solid #086856;padding:0 0 12px;margin-bottom:14px}.brand{font-size:23px;font-weight:700;letter-spacing:-.7px;color:#064e42}.brand span{display:block;color:#778985;font-size:10px;letter-spacing:2px;text-transform:uppercase;margin-top:3px}.meta{text-align:right;color:#62716d;line-height:1.8}.meta b{color:#18312c}.kpis{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;margin-bottom:14px}.kpi{border:1px solid #dce9e5;background:#f3f8f6;border-radius:8px;padding:8px 10px}.kpi span{display:block;color:#71817d;font-size:9px;text-transform:uppercase;letter-spacing:.7px}.kpi strong{display:block;font-size:15px;margin-top:3px;font-variant-numeric:tabular-nums}.green{color:#08785e}.red{color:#c33f49}.section{display:flex;justify-content:space-between;align-items:end;margin:0 0 7px}.section h2{font-size:13px;margin:0}.section small{color:#74827f}table{width:100%;border-collapse:collapse;table-layout:fixed}thead{display:table-header-group}th{background:#086856;color:white;text-align:left;padding:6px 5px;font-size:8px;text-transform:uppercase;letter-spacing:.35px}td{border-bottom:1px solid #e2eae7;padding:5px;vertical-align:top;font-size:8px;overflow-wrap:anywhere}tbody tr:nth-child(even){background:#f7faf9}.yes,.up{color:#07815e;font-weight:bold}.no,.down{color:#c8434d;font-weight:bold}.pnl{font-variant-numeric:tabular-nums;white-space:nowrap}.notes{color:#596966}.foot{margin-top:9px;color:#75837f;font-size:8px}.empty{padding:28px;text-align:center;border:1px dashed #bfd0ca;border-radius:8px;color:#71817d}@media print{body{-webkit-print-color-adjust:exact;print-color-adjust:exact}.kpi,th,tbody tr:nth-child(even){-webkit-print-color-adjust:exact;print-color-adjust:exact}}</style></head><body><header class="head"><div class="brand">Trading Journal<span>Trading journal · Performance report</span></div><div class="meta"><b>${escapeHTML(selectedAccount)}</b><br>${ts.length} trades · Generated ${titleDate}<br>Net P&amp;L uses closed trades only</div></header><section class="kpis"><div class="kpi"><span>Net P&amp;L</span><strong class="${m.net>=0?'green':'red'}">${money(m.net)}</strong></div><div class="kpi"><span>Closed trades</span><strong>${m.closed}</strong></div><div class="kpi"><span>Win rate</span><strong>${rate}</strong></div><div class="kpi"><span>Profit factor</span><strong>${factor}</strong></div><div class="kpi"><span>Expectancy / trade</span><strong>${money(m.expectancy)}</strong></div></section><section class="section"><h2>Trade records</h2><small>Positive and negative results are labeled; open positions are not included in realized P&amp;L.</small></section>${rows?`<table><thead><tr><th>Date</th><th>Symbol</th><th>Side</th><th>Status</th><th>Entry</th><th>Exit</th><th>Stop loss</th><th>Take profit</th><th>Qty / lots</th><th>Setup</th><th>Emotion</th><th>Rules</th><th>Net P&amp;L</th><th>Notes</th></tr></thead><tbody>${rows}</tbody></table>`:'<div class="empty">No trades in this report. Adjust the account or period filters and export again.</div>'}<div class="foot">Trading Journal · Historical journal calculations for reflection only · Currency values use the app’s selected currency.</div><script>window.addEventListener('load',()=>setTimeout(()=>window.print(),250));</script></body></html>`);reportWindow.document.close();notify('PDF report opened — choose Save as PDF in the print dialog.');}
async function importJSON(e:Event){const input=e.target as HTMLInputElement,file=input.files?.[0];if(!file)return;try{const incoming=restore(await file.text()),summary=`Backup contains ${incoming.trades.length} trades, ${incoming.accounts.length} accounts and ${incoming.reviews.length} reviews.\n\nReplace all local data or merge records by ID?`;const replace=confirm(summary+'\n\nChoose OK to replace all; Cancel to merge.');if(replace){if(confirm('Replace all current records with this backup? This cannot be undone.'))state=incoming;}else{const ids=new Set(state.trades.map(t=>t.id));state.trades.push(...incoming.trades.filter(t=>!ids.has(t.id)));const acc=new Set(state.accounts.map(a=>a.id));state.accounts.push(...incoming.accounts.filter(a=>!acc.has(a.id)));const rev=new Set(state.reviews.map(r=>r.date));state.reviews.push(...incoming.reviews.filter(r=>!rev.has(r.date)));}persist();app();notify('Backup imported');}catch(err){notify(err instanceof Error?err.message:'Could not read this backup.');}finally{input.value='';}}
function csvImport(){const input=document.createElement('input');input.type='file';input.accept='.csv,text/csv';input.onchange=async()=>{const file=input.files?.[0];if(!file)return;try{const text=await file.text(),rows=parseCSV(text);if(rows.length<2)throw new Error('CSV needs a header row and at least one trade.');const headers=rows[0].map(x=>x.trim()),normalize=(x:string)=>x.toLowerCase().replace(/[^a-z0-9]/g,''),aliases:Record<string,string[]>={entry:['entry','entryprice'],exit:['exit','exitprice'],stop:['stop','stoploss'],target:['target','takeprofit'],quantity:['quantity','quantitylots','lots'],rules:['rules','followedrules'],accountId:['accountid']},ix=(key:string)=>headers.findIndex(h=>(aliases[key]||[key]).includes(normalize(h)));if(['date','symbol','direction','entry'].some(k=>ix(k)<0))throw new Error('Required columns: date, symbol, direction, entry. Exported Trading Journal CSV has all columns.');const imported=rows.slice(1).filter(r=>r.some(Boolean)).map(r=>{const val=(k:string)=>r[ix(k)]??'',dir=val('direction').toLowerCase();const status=val('status').toLowerCase()==='open'?'Open':'Closed';return {id:val('id')||crypto.randomUUID(),date:val('date'),symbol:val('symbol').toUpperCase(),direction:dir==='short'?'Short':'Long',status,entry:Number(val('entry')),exit:val('exit')?Number(val('exit')):null,stop:val('stop')?Number(val('stop')):null,target:val('target')?Number(val('target')):null,quantity:Number(val('quantity')||1),multiplier:Number(val('multiplier')||1),fees:Number(val('fees')||0),manualNet:val('manualNet')?Number(val('manualNet')):val('netPnl')?Number(val('netPnl')):null,strategy:val('strategy'),setup:val('setup'),emotion:val('emotion'),rules:['true','yes','1'].includes(val('rules').toLowerCase()),notes:val('notes'),accountId:val('accountId')||state.accounts.find(a=>a.name.toLowerCase()===val('account').toLowerCase())?.id||state.accounts[0].id,createdAt:new Date().toISOString()} as Trade;}).filter(t=>t.date&&t.symbol&&Number.isFinite(t.entry)&&Number.isFinite(t.quantity));const ids=new Set(state.trades.map(t=>t.id));const fresh=imported.filter(t=>!ids.has(t.id));if(confirm(`${imported.length} valid rows found; ${fresh.length} are new and ${imported.length-fresh.length} duplicate IDs. Import ${fresh.length} new trades?`)){state.trades.push(...fresh);persist();app();notify(`${fresh.length} trades imported`);}}catch(err){notify(err instanceof Error?err.message:'CSV import failed.');}};input.click();}
function parseCSV(text:string){const rows:string[][]=[];let row:string[]=[],field='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){field+='"';i++;}else if(c==='"')quoted=false;else field+=c;}else if(c==='"')quoted=true;else if(c===','){row.push(field);field='';}else if(c==='\n'){row.push(field.replace(/\r$/,''));rows.push(row);row=[];field='';}else field+=c;}if(field||row.length){row.push(field.replace(/\r$/,''));rows.push(row);}return rows;}
function deleteAccount(id:string) {
  const accountToDelete=state.accounts.find(a=>a.id===id);
  if(!accountToDelete)return;
  if(state.accounts.length<=1){notify('Keep at least one trading account.');return;}
  const linkedTrades=state.trades.filter(t=>t.accountId===id).length;
  if(linkedTrades){notify('This account still has trades. Reassign or delete those trades before deleting the account.');return;}
  if(!confirm(`Delete the account \u201c${accountToDelete.name}\u201d? This cannot be undone.`))return;
  state.accounts=state.accounts.filter(a=>a.id!==id);
  if(account===id)account='all';
  persist();app();notify('Account deleted');
}
function saveReview(){const date=($('#review-date') as HTMLInputElement).value,plan=($('#review-plan') as HTMLTextAreaElement).value,review=($('#review-review') as HTMLTextAreaElement).value,lesson=($('#review-lesson') as HTMLTextAreaElement).value;if(!date){notify('Choose a date for this review.');return;}state.reviews=state.reviews.filter(r=>r.date!==date);state.reviews.push({date,plan,review,lesson,updatedAt:new Date().toISOString()});persist();app();notify('Daily review saved');}
function mergeRemote(remote:AppState){const priorIds=new Set<string>(JSON.parse(localStorage.getItem(userStorageKey('google-last-trade-ids'))||'[]')),cloudIds=new Set(remote.trades.map(t=>t.id)),trades=new Map(remote.trades.filter(t=>!deletedTradeIds.has(t.id)).map(t=>[t.id,t]));for(const local of state.trades){if(deletedTradeIds.has(local.id)||(!cloudIds.has(local.id)&&priorIds.has(local.id)))continue;const cloud=trades.get(local.id);if(!cloud||(local.createdAt||'')>=(cloud.createdAt||''))trades.set(local.id,local);}const accounts=new Map(remote.accounts.map(a=>[a.id,a]));for(const local of state.accounts)if(!accounts.has(local.id))accounts.set(local.id,local);const reviews=new Map(remote.reviews.map(r=>[r.date,r]));for(const local of state.reviews){const cloud=reviews.get(local.date);if(!cloud||(local.updatedAt||'')>(cloud.updatedAt||''))reviews.set(local.date,local);}state={...remote,trades:[...trades.values()],accounts:[...accounts.values()],reviews:[...reviews.values()],settings:state.settings};}
async function syncSheets(showStatus:boolean){const config=readSheetsConfig();try{const spreadsheetId=await getOrCreateJournalSpreadsheet();saveSheetsConfig({...config,spreadsheetId});const remote=await readCloudState(spreadsheetId);if(remote)mergeRemote(remote);save(state);await writeCloudState(spreadsheetId,state);localStorage.setItem(userStorageKey('google-last-trade-ids'),JSON.stringify(state.trades.map(t=>t.id)));deletedTradeIds.clear();localStorage.setItem(userStorageKey('google-deleted-trades'),'[]');sheetsConnected=true;scheduleCloudPoll();if(showStatus){notify('Journal synced with Google Sheets');app();}}catch(error){sheetsConnected=false;notify(error instanceof Error?`Saved on this device; sync needs attention: ${error.message}`:'Saved on this device; Google Sheets sync failed.');}}
function scheduleCloudPoll(){clearTimeout(cloudPollTimer);if(sheetsConnected)cloudPollTimer=setTimeout(()=>void pollCloud(),30000);}
async function pollCloud(){if(!sheetsConnected)return;if(document.hidden){scheduleCloudPoll();return;}try{const remote=await readCloudState(readSheetsConfig().spreadsheetId);if(remote){const before=JSON.stringify(state);mergeRemote(remote);if(JSON.stringify(state)!==before){save(state);const active=document.activeElement,modalOpen=$('#modal-root').childElementCount>0;if(!modalOpen&&!(active instanceof HTMLInputElement)&&!(active instanceof HTMLTextAreaElement)&&!(active instanceof HTMLSelectElement)){app();notify('Journal updated from Google Sheets');}}}scheduleCloudPoll();}catch(error){sheetsConnected=false;notify(error instanceof Error?`Google sync paused: ${error.message}`:'Google sync paused. Reconnect from Settings.');}}
async function resumeGoogleSession(){if(!signedInEmail)return;try{const config=readSheetsConfig();await authorizeSheets(config.clientId,false);const user=await getGoogleUser();if(user.email.toLowerCase()!==signedInEmail.toLowerCase())throw new Error('Google account does not match the remembered journal. Reconnect from Settings.');const spreadsheetId=await getOrCreateJournalSpreadsheet();saveSheetsConfig({clientId:config.clientId,spreadsheetId});await syncSheets(false);app();}catch{clearGoogleAuthorization();sheetsConnected=false;app();}}
async function connectGoogleSheets(){const clientId=(($('#login-client-id')||$('#google-client-id')) as HTMLInputElement| null)?.value.trim()||readSheetsConfig().clientId;if(!clientId){notify('Enter your Google OAuth web client ID first.');return;}const button=$('#google-login') as HTMLButtonElement|null;if(button){button.disabled=true;button.textContent='Connecting to Google…';}try{await authorizeSheets(clientId,true);const user=await getGoogleUser();signedInEmail=user.email;googleName=user.name||'';const spreadsheetId=await getOrCreateJournalSpreadsheet();saveSheetsConfig({clientId,spreadsheetId});localStorage.setItem(AUTH_EMAIL_KEY,signedInEmail);setStorageUser(signedInEmail);deletedTradeIds.clear();try{for(const id of JSON.parse(localStorage.getItem(userStorageKey('google-deleted-trades'))||'[]'))if(typeof id==='string')deletedTradeIds.add(id);}catch{}if(!hasUserStorage()){const legacy=loadLegacy();if(legacy.trades.length||legacy.reviews.length||legacy.accounts.some(a=>a.id!=='default')){if(confirm(`Import this browser's existing journal into ${signedInEmail}? Choose Cancel to keep the accounts separate.`))state=legacy;else state=load();}else state=load();}else state=load();account='all';app();await syncSheets(true);app();}catch(error){signedInEmail='';clearGoogleAuthorization();if(button){button.disabled=false;button.innerHTML='<span class="google-g">G</span>Continue with Google';}const message=error instanceof Error?error.message:'Google connection failed.';const errorBox=$('#auth-error');if(errorBox)errorBox.textContent=message;else notify(message);}}
function showAccountForm(existing?:AppState['accounts'][number]){const root=$('#modal-root'),today=new Date().toISOString().slice(0,10);root.innerHTML=`<div class="modal-backdrop"><form class="trade-modal" id="account-form"><div class="modal-head"><div><div class="eyebrow">ACCOUNT PROFILE</div><h2>${existing?'Edit trading account':'Add trading account'}</h2></div><button type="button" class="icon-btn modal-close" data-action="close" aria-label="Close">×</button></div><div class="form-scroll"><div class="form-grid"><label>Account name<input name="name" placeholder="e.g. Main account" value="${escapeHTML(existing?.name||'')}" required></label><label>Broker or platform<input name="broker" placeholder="Optional" value="${escapeHTML(existing?.broker||'')}"></label><label>Account type<select name="accountType">${['Personal','Demo','Prop firm','Retirement'].map(x=>`<option ${(existing?.accountType||'Personal')===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Base currency<select name="currency">${['USD','EUR','GBP','INR','JPY','CAD','AUD'].map(c=>`<option ${(existing?.currency||state.settings.currency)===c?'selected':''}>${c}</option>`).join('')}</select></label><label>Starting balance<input name="balance" type="number" min="0" step="any" value="${existing?.balance??10000}" required></label><label>Start date<input name="startDate" type="date" value="${existing?.startDate||today}"></label></div><p class="form-hint">Starting balance is the baseline used for this account’s balance and return calculations.</p></div><div class="modal-actions"><button type="button" class="btn soft" data-action="close">Cancel</button><button class="btn primary" type="submit">${existing?'Save changes':'Save account'}</button></div></form></div>`;($('#account-form') as HTMLFormElement).addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.currentTarget as HTMLFormElement),name=String(d.get('name')).trim();if(!name)return;const updated={...(existing||{id:crypto.randomUUID()}),name,broker:String(d.get('broker')).trim(),accountType:String(d.get('accountType')),currency:String(d.get('currency')),balance:Number(d.get('balance')),startDate:String(d.get('startDate'))};if(existing){const index=state.accounts.findIndex(a=>a.id===existing.id);if(index>=0)state.accounts[index]=updated;}else state.accounts.push(updated);persist();root.innerHTML='';app();notify(existing?'Account updated':'Account saved');});}
document.addEventListener('click',ev=>{const target=ev.target;if(!(target instanceof Element))return;if(target.closest('#modal-root [data-action="close"]')){ev.preventDefault();$('#modal-root').innerHTML='';return;}if(target.matches('#modal-root .modal-backdrop'))$('#modal-root').innerHTML='';});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&$('#modal-root').childElementCount>0)$('#modal-root').innerHTML='';if(ev.key==='Escape')document.querySelector('.sidebar')?.classList.remove('mobile-open');});
app();
if(signedInEmail)void resumeGoogleSession();
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register(`${import.meta.env.BASE_URL}sw.js`).catch(()=>{}));
